      es: ["Tipo: Carretera panorámica", "Ubicación: Selva Negra Septentrional", "Altitud: 600–1000 m", "Estado: B500"],
      pt: ["Tipo: Estrada panorâmica", "Localização: Floresta Negra do Norte", "Altitude: 600–1000 m", "Status: B500"],
      fr: ["Type : Route panoramique", "Lieu : Forêt-Noire du Nord", "Altitude : 600–1000 m", "Statut : B500"],
